// First generated by uniffi-bindgen-react-native, then maintained by hand.
// ubrn.config.yaml lists this file under noOverwrite, because it also
// registers CoproductStorageModule
package app.coproduct

import com.facebook.react.TurboReactPackage
import com.facebook.react.bridge.NativeModule
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.module.model.ReactModuleInfo
import com.facebook.react.module.model.ReactModuleInfoProvider
import java.util.HashMap

class CoproductPackage : TurboReactPackage() {
  override fun getModule(name: String, reactContext: ReactApplicationContext): NativeModule? {
    return when (name) {
      CoproductModule.NAME -> CoproductModule(reactContext)
      CoproductStorageModule.NAME -> CoproductStorageModule(reactContext)
      else -> null
    }
  }

  override fun getReactModuleInfoProvider(): ReactModuleInfoProvider {
    return ReactModuleInfoProvider {
      val moduleInfos: MutableMap<String, ReactModuleInfo> = HashMap()
      moduleInfos[CoproductModule.NAME] = ReactModuleInfo(
        CoproductModule.NAME,
        CoproductModule.NAME,
        false,  // canOverrideExistingModule
        false,  // needsEagerInit
        false,  // isCxxModule
        true // isTurboModule
      )
      moduleInfos[CoproductStorageModule.NAME] = ReactModuleInfo(
        CoproductStorageModule.NAME,
        CoproductStorageModule.NAME,
        false,  // canOverrideExistingModule
        false,  // needsEagerInit
        false,  // isCxxModule
        true // isTurboModule
      )
      moduleInfos
    }
  }
}